CREATE OR REPLACE FUNCTION public.capture_registration_consents() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.registration_forms; d jsonb; accepted boolean; BEGIN SELECT * INTO f FROM public.registration_forms WHERE id=new.form_id FOR SHARE; new.consent_snapshot:='[]'::jsonb; FOR d IN SELECT * FROM jsonb_array_elements(f.legal_documents) LOOP accepted:=coalesce(new.answers->>('consent_'||(d->>'id')),'')='true'; IF coalesce((d->>'required')::boolean,false) AND NOT accepted THEN RAISE EXCEPTION 'Aceite obrigatório: %',d->>'title'; END IF; new.consent_snapshot:=new.consent_snapshot||jsonb_build_array(d||jsonb_build_object('agreed',accepted,'accepted_at',new.created_at)); END LOOP; new.submission_snapshot:=jsonb_build_object('full_name',new.full_name,'email',new.email,'answers',new.answers,'title',f.title,'category',f.category,'created_at',new.created_at); RETURN new; END $$;
ALTER TABLE public.registration_dossier_access ADD COLUMN requests integer NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.check_dossier_request(_token_hash text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.registration_dossier_access SET requests=requests+1 WHERE token_hash=_token_hash AND expires_at>now() AND requests<60; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.check_dossier_request(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.check_dossier_request(text) TO service_role;